/* ==========================================================
   TRAINING AGENCY LIVE QUIZ - ANIMATIONS & TRANSITIONS
   ========================================================== */

/* Fade in scale */
@keyframes fadeInScale {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.animate-fade-in {
  animation: fadeInScale 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Slide up */
@keyframes slideUpFade {
  from {
    opacity: 0;
    transform: translateY(25px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-slide-up {
  animation: slideUpFade 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Podium Rise Animations */
@keyframes podiumRise1st {
  0% { transform: translateY(100%); opacity: 0; }
  60% { transform: translateY(-10px); }
  100% { transform: translateY(0); opacity: 1; }
}

@keyframes podiumRise2nd {
  0% { transform: translateY(100%); opacity: 0; }
  60% { transform: translateY(-8px); }
  100% { transform: translateY(0); opacity: 1; }
}

@keyframes podiumRise3rd {
  0% { transform: translateY(100%); opacity: 0; }
  60% { transform: translateY(-6px); }
  100% { transform: translateY(0); opacity: 1; }
}

.podium-1st {
  animation: podiumRise1st 0.9s 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275) both;
}

.podium-2nd {
  animation: podiumRise2nd 0.8s 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) both;
}

.podium-3rd {
  animation: podiumRise3rd 0.7s 0.1s cubic-bezier(0.175, 0.885, 0.32, 1.275) both;
}

/* Float Glow Animation */
@keyframes floatGlow {
  0%, 100% {
    transform: translateY(0);
    box-shadow: 0 0 20px rgba(99, 102, 241, 0.4);
  }
  50% {
    transform: translateY(-6px);
    box-shadow: 0 0 35px rgba(99, 102, 241, 0.7);
  }
}

.animate-float {
  animation: floatGlow 3s ease-in-out infinite;
}

/* Pulse Badge */
@keyframes pulseSubtle {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(1.04); }
}

.animate-pulse {
  animation: pulseSubtle 2s infinite ease-in-out;
}

/* Shake on Wrong Answer */
@keyframes shakeWrong {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-8px); }
  40%, 80% { transform: translateX(8px); }
}

.animate-shake {
  animation: shakeWrong 0.5s ease-in-out;
}

/* Success Bounce */
@keyframes bounceSuccess {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

.animate-bounce {
  animation: bounceSuccess 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* Avatar Pop In for Lobby */
@keyframes avatarPop {
  0% { transform: scale(0); opacity: 0; }
  70% { transform: scale(1.15); }
  100% { transform: scale(1); opacity: 1; }
}

.player-bubble {
  animation: avatarPop 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
