      return [];
    }
  }

  updateParticipantRecords(gameResult) {
    let records = this.getParticipantRecords();
    gameResult.players.forEach(player => {
      records.push({
        id: 'rec_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
        name: player.name,
        training_name: gameResult.training_name || gameResult.quiz_name,
        quiz_name: gameResult.quiz_name,
        level: gameResult.level || 'Basic',
        subject: gameResult.subject || 'General',
        trainer_name: gameResult.trainer_name || 'Admin',
        score: player.score,
        rank: player.rank,
        correct_count: player.correct || 0,
        total_questions: gameResult.total_questions || 10,
        completion_percent: Math.round(((player.correct || 0) / (gameResult.total_questions || 1)) * 100),
        date: gameResult.date || new Date().toISOString()
      });
    });
    localStorage.setItem(this.KEYS.PARTICIPANT_RECORDS, JSON.stringify(records));
  }

  // Supabase Configuration
  getSupabaseConfig() {
    try {
      return JSON.parse(localStorage.getItem(this.KEYS.SUPABASE_CONFIG)) || { url: '', anonKey: '', enabled: false };
    } catch (e) {
      return { url: '', anonKey: '', enabled: false };
    }
  }

  saveSupabaseConfig(config) {
    localStorage.setItem(this.KEYS.SUPABASE_CONFIG, JSON.stringify(config));
  }

  // Admin Auth State
  isAdminLoggedIn() {
    return localStorage.getItem(this.KEYS.ADMIN_AUTH) === 'true';
  }

  setAdminLoggedIn(status) {
    localStorage.setItem(this.KEYS.ADMIN_AUTH, status ? 'true' : 'false');
  }
}

