/**
 * Scoring Engine - Implements PRD Section 6
 * Formula: Score = Math.round(Base Point * (Remaining Time / Total Time))
 * Wrong answer = 0
 */
class ScoringEngine {
  /**
   * Calculate score for a participant submission
   * @param {boolean} isCorrect - whether answer matches question correct_answer
   * @param {number} responseTimeSeconds - time taken by participant to answer in seconds
   * @param {number} totalTimeLimitSeconds - question total time limit (e.g., 20)
   * @param {number} basePoint - base question points (default 1000)
   * @returns {number} calculated score integer
   */
  static calculateScore(isCorrect, responseTimeSeconds, totalTimeLimitSeconds = 20, basePoint = 1000) {
    if (!isCorrect) {
      return 0;
    }

    if (totalTimeLimitSeconds <= 0) totalTimeLimitSeconds = 20;

    // Remaining time
    const remainingTime = Math.max(0, totalTimeLimitSeconds - responseTimeSeconds);

    // Speed ratio: answers within 0.5s get max points (1000), minimum floor is 40% of basePoint for correct answers
    const ratio = Math.min(1, Math.max(0.4, remainingTime / totalTimeLimitSeconds));

    const calculated = Math.round(basePoint * ratio);
    return Math.min(basePoint, Math.max(0, calculated));
  }

  /**
   * Calculate leaderboard rank order and streaks
   * @param {Array} players - list of player objects
   * @returns {Array} sorted players with ranks
   */
  static sortLeaderboard(players = []) {
    return [...players]
      .sort((a, b) => {
        if (b.total_score !== a.total_score) {
          return b.total_score - a.total_score;
        }
        // Tie breaker by correct count
        return (b.correct_count || 0) - (a.correct_count || 0);
      })
      .map((p, index) => ({
        ...p,
        rank: index + 1
      }));
  }
}

window.ScoringEngine = ScoringEngine;

/**
 * Realtime Event Bus - Supports BroadcastChannel (Multi-tab local) and Supabase Realtime
 */
class RealtimeBus {
  constructor() {
    this.channelName = 'ta_live_quiz_channel';
    this.listeners = new Map();
    this.bc = null;

    if (typeof BroadcastChannel !== 'undefined') {
      try {
        this.bc = new BroadcastChannel(this.channelName);
        this.bc.onmessage = (event) => {
          if (event && event.data) {
            this._dispatch(event.data.type, event.data.payload, false);
          }
        };
      } catch (e) {
        console.warn('BroadcastChannel error, fallback to storage events', e);
      }
    }

    // Fallback cross-tab storage listener
    window.addEventListener('storage', (e) => {
      if (e.key === 'ta_realtime_event' && e.newValue) {
        try {
          const data = JSON.parse(e.newValue);
          this._dispatch(data.type, data.payload, false);
        } catch (err) {}
      }
    });
  }

  /**
   * Broadcast an event to all subscribers and other open tabs/windows
   */
  emit(type, payload = {}) {
    const message = { type, payload, timestamp: Date.now() };

    // 1. Dispatch locally to current window
    this._dispatch(type, payload, true);

    // 2. BroadcastChannel to other tabs
    if (this.bc) {
      try {
        this.bc.postMessage(message);
      } catch (e) {}
    }

    // 3. Fallback Storage event trigger
    try {
      localStorage.setItem('ta_realtime_event', JSON.stringify(message));
    } catch (e) {}
  }

  /**
   * Register an event listener
   */
  on(type, callback) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type).push(callback);
    return () => this.off(type, callback);
  }

  /**
   * Unregister an event listener
   */
  off(type, callback) {
    if (!this.listeners.has(type)) return;
    const list = this.listeners.get(type).filter(cb => cb !== callback);
    this.listeners.set(type, list);
  }

  _dispatch(type, payload, isLocalOrigin) {
    if (this.listeners.has(type)) {
      this.listeners.get(type).forEach(cb => {
        try {
          cb(payload, isLocalOrigin);
        } catch (err) {
          console.error(`Error in event listener for ${type}:`, err);
        }
      });
    }

    // Also notify wildcard listeners
    if (this.listeners.has('*')) {
      this.listeners.get('*').forEach(cb => {
        try {
          cb(type, payload, isLocalOrigin);
        } catch (err) {}
      });
    }
  }
}

window.realtimeBus = new RealtimeBus();

/**
 * GameManager - State Machine & Session Orchestrator
 * Implements PRD Section 4 (User Flow), Section 5 (MVP Features), & Section 17 (Game Status)
 */
class GameManager {
  constructor() {
    this.activeGame = null;
    this.timerInterval = null;
    this.timeRemaining = 0;
    this.initEventListeners();
  }

  initEventListeners() {
    // Listen to participant actions
    window.realtimeBus.on('PLAYER_JOIN', (data) => this.handlePlayerJoin(data));
    window.realtimeBus.on('SUBMIT_ANSWER', (data) => this.handlePlayerAnswer(data));
  }

  /**
   * Generate unique 6-digit Game PIN
   */
  generatePIN() {
    return Math.floor(100000 + Math.random() * 900000).toString();
  }

  /**
   * Create and Start a new Live Game Session
   */
  createGame(quizId) {
    const quiz = window.storage.getQuizById(quizId);
    if (!quiz || !quiz.questions || quiz.questions.length === 0) {
      throw new Error('Kuis tidak memiliki pertanyaan yang valid.');
    }

    const pin = this.generatePIN();
    this.activeGame = {
      id: 'game_' + Date.now(),
      quiz_id: quiz.id,
      quiz_name: quiz.quiz_name,
      training_name: quiz.training_name || quiz.quiz_name,
      level: quiz.level || 'Basic',
      subject: quiz.subject || 'General',
      trainer_name: quiz.trainer_name || 'Trainer',
      game_pin: pin,
      status: 'LOBBY', // WAITING, LOBBY, QUESTION, RESULT, LEADERBOARD, FINISHED, CANCELLED
      current_question_index: 0,
      total_questions: quiz.questions.length,
      questions: JSON.parse(JSON.stringify(quiz.questions)),
      players: [],
      current_answers: {}, // playerId -> answer data
      start_time: new Date().toISOString(),
      max_participants: 50
    };

    // Save active game to storage for multi-tab recovery
    this.saveActiveSession();

    // Broadcast GAME_CREATED event
    window.realtimeBus.emit('GAME_CREATED', this.getPublicGameState());
    return this.activeGame;
  }

  saveActiveSession() {
    if (this.activeGame) {
      localStorage.setItem('ta_active_game_session', JSON.stringify(this.activeGame));
    } else {
      localStorage.removeItem('ta_active_game_session');
    }
  }

  getActiveGame() {
    if (!this.activeGame) {
      const saved = localStorage.getItem('ta_active_game_session');
      if (saved) {
        try {
          this.activeGame = JSON.parse(saved);
        } catch (e) {}
      }
    }
    return this.activeGame;
  }

  /**
   * Handle player joining via PIN
   */
  handlePlayerJoin({ pin, name, playerId }) {
    if (!this.activeGame || this.activeGame.game_pin !== pin) return;

    if (this.activeGame.status !== 'LOBBY' && this.activeGame.status !== 'WAITING') {
      // Allow rejoin if player already exists
      const existing = this.activeGame.players.find(p => p.id === playerId || p.name.toLowerCase() === name.toLowerCase());
      if (existing) {
        window.realtimeBus.emit('JOIN_SUCCESS', {
          player: existing,
          game: this.getPublicGameState()
        });
      } else {
        window.realtimeBus.emit('JOIN_REJECTED', {
          reason: 'Game sudah dimulai atau selesai.',
          playerId
        });
      }
      return;
    }

    if (this.activeGame.players.length >= this.activeGame.max_participants) {
      window.realtimeBus.emit('JOIN_REJECTED', {
        reason: 'Lobby penuh (Maksimal 50 peserta).',
        playerId
      });
      return;
    }

    // Check duplicate name
    const trimmedName = name.trim();
    const existingPlayer = this.activeGame.players.find(p => p.name.toLowerCase() === trimmedName.toLowerCase());
    const id = playerId || 'p_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);

    let playerObj;
    if (existingPlayer) {
      playerObj = existingPlayer;
    } else {
      playerObj = {
        id,
        name: trimmedName,
        total_score: 0,
        correct_count: 0,
        streak: 0,
        rank: this.activeGame.players.length + 1,
        joined_at: new Date().toISOString()
      };
      this.activeGame.players.push(playerObj);
    }

    this.saveActiveSession();

    // Broadcast update
    window.realtimeBus.emit('PLAYER_JOINED', {
      player: playerObj,
      totalPlayers: this.activeGame.players.length,
      players: this.activeGame.players,
      game: this.getPublicGameState()
    });

    window.realtimeBus.emit('JOIN_SUCCESS', {
      player: playerObj,
      game: this.getPublicGameState()
    });
  }

  /**
   * Start Live Question Presentation
   */
  startQuestion(questionIndex = 0) {
    if (!this.activeGame) return;

    this.clearIntervalTimer();
    this.activeGame.current_question_index = questionIndex;
    this.activeGame.status = 'QUESTION';
    this.activeGame.current_answers = {};

    const question = this.activeGame.questions[questionIndex];
    this.timeRemaining = question.time_limit || 20;
    this.activeGame.question_start_time = Date.now();
    this.activeGame.question_time_limit = this.timeRemaining;

    this.saveActiveSession();

    // Broadcast to trainer screen and all mobile players
    window.realtimeBus.emit('QUESTION_START', {
      questionIndex,
      totalQuestions: this.activeGame.total_questions,
      question: {
        id: question.id,
        question: question.question,
        question_type: question.question_type,
        option_a: question.option_a,
        option_b: question.option_b,
        option_c: question.option_c,
        option_d: question.option_d,
        time_limit: question.time_limit,
        point: question.point,
        order_index: question.order_index
      },
      timeLimit: this.timeRemaining,
      answeredCount: 0,
      totalPlayers: this.activeGame.players.length
    });

    // Start Host Timer Countdown
    this.startTimerCountdown();
  }

  startTimerCountdown() {
    this.clearIntervalTimer();
    this.timerInterval = setInterval(() => {
      this.timeRemaining--;

      window.realtimeBus.emit('TIMER_TICK', {
        timeRemaining: this.timeRemaining,
        totalTime: this.activeGame.question_time_limit
      });

      if (this.timeRemaining <= 0) {
        this.clearIntervalTimer();
        this.endQuestion();
      }
    }, 1000);
  }

  clearIntervalTimer() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
  }

  /**
   * Handle Answer Submission from Participant
   */
  handlePlayerAnswer({ playerId, answer, responseTime }) {
    if (!this.activeGame || this.activeGame.status !== 'QUESTION') return;

    const currentQ = this.activeGame.questions[this.activeGame.current_question_index];
    if (!currentQ) return;

    // Check if player already answered
    if (this.activeGame.current_answers[playerId]) return;

    const isCorrect = String(answer).toUpperCase() === String(currentQ.correct_answer).toUpperCase();
    const respTimeSec = responseTime || (currentQ.time_limit - Math.max(0, this.timeRemaining));
    const scoreEarned = window.ScoringEngine.calculateScore(
      isCorrect,
      respTimeSec,
      currentQ.time_limit,
      currentQ.point || 1000
    );

    const answerRecord = {
      playerId,
      answer,
      isCorrect,
      responseTime: respTimeSec,
      scoreEarned,
      answeredAt: Date.now()
    };

    this.activeGame.current_answers[playerId] = answerRecord;

    // Update Player Stats
    const player = this.activeGame.players.find(p => p.id === playerId);
    if (player) {
      player.total_score = (player.total_score || 0) + scoreEarned;
      if (isCorrect) {
        player.correct_count = (player.correct_count || 0) + 1;
        player.streak = (player.streak || 0) + 1;
      } else {
        player.streak = 0;
      }
    }

    this.saveActiveSession();

    // Broadcast real-time answer counter to host
    const answeredCount = Object.keys(this.activeGame.current_answers).length;
    window.realtimeBus.emit('ANSWER_COUNT_UPDATE', {
      answeredCount,
      totalPlayers: this.activeGame.players.length
    });

    // Notify player that answer is locked in
    window.realtimeBus.emit('ANSWER_LOCKED', {
      playerId,
      scoreEarned,
      isCorrect
    });

    // If all joined players answered, end question immediately!
    if (this.activeGame.players.length > 0 && answeredCount >= this.activeGame.players.length) {
      this.clearIntervalTimer();
      setTimeout(() => this.endQuestion(), 400);
    }
  }

  /**
   * End Current Question & Show Result / Answer Distribution
   */
  endQuestion() {
    this.clearIntervalTimer();
    if (!this.activeGame) return;

    this.activeGame.status = 'RESULT';
    const currentQ = this.activeGame.questions[this.activeGame.current_question_index];

    // Compute distribution counts (A, B, C, D)
    const distribution = { A: 0, B: 0, C: 0, D: 0, TRUE: 0, FALSE: 0 };
    Object.values(this.activeGame.current_answers).forEach(ans => {
      const key = String(ans.answer).toUpperCase();
      if (distribution[key] !== undefined) {
        distribution[key]++;
      }
    });

    // Recalculate leaderboard
    this.activeGame.players = window.ScoringEngine.sortLeaderboard(this.activeGame.players);
    this.saveActiveSession();

    // Broadcast QUESTION_ENDED event
    window.realtimeBus.emit('QUESTION_ENDED', {
      questionIndex: this.activeGame.current_question_index,
      correctAnswer: currentQ.correct_answer,
      explanation: currentQ.explanation,
      distribution,
      currentAnswers: this.activeGame.current_answers,
      players: this.activeGame.players,
      isLastQuestion: this.activeGame.current_question_index >= this.activeGame.total_questions - 1
    });
  }

  /**
   * Show Leaderboard Screen
   */
  showLeaderboard() {
    if (!this.activeGame) return;
    this.activeGame.status = 'LEADERBOARD';
    this.activeGame.players = window.ScoringEngine.sortLeaderboard(this.activeGame.players);
    this.saveActiveSession();

    window.realtimeBus.emit('LEADERBOARD_UPDATE', {
      players: this.activeGame.players,
      questionIndex: this.activeGame.current_question_index,
      totalQuestions: this.activeGame.total_questions,
      isLastQuestion: this.activeGame.current_question_index >= this.activeGame.total_questions - 1
    });
  }

  /**
   * Advance to next question or finish game
   */
  nextQuestion() {
    if (!this.activeGame) return;
    const nextIdx = this.activeGame.current_question_index + 1;
    if (nextIdx < this.activeGame.total_questions) {
      this.startQuestion(nextIdx);
    } else {
      this.finishGame();
    }
  }

  /**
   * Finish Game & Show Final Winner Podium
   */
  finishGame() {
    if (!this.activeGame) return;
    this.clearIntervalTimer();
    this.activeGame.status = 'FINISHED';
    this.activeGame.end_time = new Date().toISOString();
    this.activeGame.players = window.ScoringEngine.sortLeaderboard(this.activeGame.players);

    // Save result to History & Records
    const avgScore = this.activeGame.players.length > 0
      ? Math.round(this.activeGame.players.reduce((sum, p) => sum + (p.total_score || 0), 0) / this.activeGame.players.length)
      : 0;

    const gameRecord = {
      id: this.activeGame.id,
      game_pin: this.activeGame.game_pin,
      quiz_name: this.activeGame.quiz_name,
      training_name: this.activeGame.training_name,
      level: this.activeGame.level,
      subject: this.activeGame.subject,
      trainer_name: this.activeGame.trainer_name,
      date: this.activeGame.start_time,
      participant_count: this.activeGame.players.length,
      total_questions: this.activeGame.total_questions,
      average_score: avgScore,
      players: this.activeGame.players
    };

    window.storage.saveGameResult(gameRecord);
    this.saveActiveSession();

    window.realtimeBus.emit('GAME_FINISHED', {
      game: gameRecord,
      winners: this.activeGame.players.slice(0, 3),
      allPlayers: this.activeGame.players
    });
  }

  /**
   * Cancel Game
   */
  cancelGame() {
    this.clearIntervalTimer();
    if (this.activeGame) {
      this.activeGame.status = 'CANCELLED';
      window.realtimeBus.emit('GAME_CANCELLED', { pin: this.activeGame.game_pin });
      this.activeGame = null;
      this.saveActiveSession();
    }
  }

  getPublicGameState() {
    if (!this.activeGame) return null;
    return {
      id: this.activeGame.id,
      quiz_name: this.activeGame.quiz_name,
      training_name: this.activeGame.training_name,
      game_pin: this.activeGame.game_pin,
      status: this.activeGame.status,
      current_question_index: this.activeGame.current_question_index,
      total_questions: this.activeGame.total_questions,
      player_count: this.activeGame.players.length,
      trainer_name: this.activeGame.trainer_name
    };
  }
}

