        if (!isRight) {
          if (currentQ.question_type === 'true_false') {
            chosenAnswer = currentQ.correct_answer === 'A' || currentQ.correct_answer === 'TRUE' ? 'B' : 'A';
          } else {
            const wrongOptions = ['A', 'B', 'C', 'D'].filter(opt => opt !== currentQ.correct_answer);
            chosenAnswer = wrongOptions[Math.floor(Math.random() * wrongOptions.length)];
          }
        }

        window.realtimeBus.emit('SUBMIT_ANSWER', {
          playerId: bot.id,
          answer: chosenAnswer,
          responseTime: answerDelay
        });
      }, answerDelay * 1000);
    });
  }
}

