  addQuestion(type = 'multiple_choice') {
    this.collectFormData();
    this.currentEditingQuiz.questions.push({
      id: 'q_' + Date.now() + '_' + (this.currentEditingQuiz.questions.length + 1),
      question: '',
      question_type: type,
      option_a: type === 'true_false' ? 'Benar (True)' : '',
      option_b: type === 'true_false' ? 'Salah (False)' : '',
      option_c: '',
      option_d: '',
      correct_answer: 'A',
      explanation: '',
      time_limit: 20,
      point: 1000,
      order_index: this.currentEditingQuiz.questions.length + 1
    });
    this.renderModal();
  }

  removeQuestion(index) {
    this.collectFormData();
    if (this.currentEditingQuiz.questions.length <= 1) {
      window.app.showToast('Kuis harus memiliki minimal 1 pertanyaan.', 'warning');
      return;
    }
    this.currentEditingQuiz.questions.splice(index, 1);
    this.renderModal();
  }

  collectFormData() {
    if (!this.currentEditingQuiz) return;

    this.currentEditingQuiz.quiz_name = document.getElementById('quiz-name-input')?.value || '';
    this.currentEditingQuiz.training_name = document.getElementById('quiz-training-input')?.value || '';
    this.currentEditingQuiz.level = document.getElementById('quiz-level-input')?.value || 'Basic';
    this.currentEditingQuiz.subject = document.getElementById('quiz-subject-input')?.value || '';
    this.currentEditingQuiz.trainer_name = document.getElementById('quiz-trainer-input')?.value || '';
    this.currentEditingQuiz.description = document.getElementById('quiz-desc-input')?.value || '';

    const cards = document.querySelectorAll('.question-item-card');
    cards.forEach((card, idx) => {
      const q = this.currentEditingQuiz.questions[idx];
      if (!q) return;

      q.question = card.querySelector('.q-text-input')?.value || '';
      q.time_limit = parseInt(card.querySelector('.q-timer-input')?.value || '20', 10);
      q.explanation = card.querySelector('.q-explanation-input')?.value || '';

      const selectedRadio = card.querySelector('input[type="radio"]:checked');
      if (selectedRadio) {
        q.correct_answer = selectedRadio.value;
      }

      if (q.question_type !== 'true_false') {
        q.option_a = card.querySelector('.q-opt-a')?.value || '';
        q.option_b = card.querySelector('.q-opt-b')?.value || '';
        q.option_c = card.querySelector('.q-opt-c')?.value || '';
        q.option_d = card.querySelector('.q-opt-d')?.value || '';
      }
    });
  }

  saveQuiz() {
    this.collectFormData();
    const quiz = this.currentEditingQuiz;

    if (!quiz.quiz_name.trim()) {
      window.app.showToast('Mohon masukkan Nama Quiz!', 'warning');
      return;
    }

    for (let i = 0; i < quiz.questions.length; i++) {
      const q = quiz.questions[i];
      if (!q.question.trim()) {
        window.app.showToast(`Pertanyaan #${i + 1} belum diisi!`, 'warning');
        return;
      }
      if (q.question_type === 'multiple_choice') {
        if (!q.option_a.trim() || !q.option_b.trim()) {
          window.app.showToast(`Pertanyaan #${i + 1} minimal harus memiliki Opsi A dan B!`, 'warning');
          return;
        }
      }
    }

    window.storage.saveQuiz(quiz);
    window.app.showToast('Quiz berhasil disimpan! 🎉', 'success');
    this.closeModal();
    window.app.renderCurrentView();
  }

  deleteQuiz(quizId) {
    if (confirm('Apakah Anda yakin ingin menghapus kuis ini?')) {
      window.storage.deleteQuiz(quizId);
      window.app.showToast('Quiz telah dihapus.', 'info');
      this.closeModal();
      window.app.renderCurrentView();
    }
  }

  closeModal() {
    const modal = document.getElementById('quiz-editor-modal');
    if (modal) {
      modal.remove();
    }
  }
}

