/**
 * Participant (Peserta) Mobile View
 * Implements PRD Section 2.B, Section 4 (Peserta Flow), Section 5, & Section 21
 */
class ParticipantView {
  constructor() {
    this.currentPlayer = null;
    this.currentGamePin = null;
    this.currentGameState = 'JOIN'; // 'JOIN', 'WAITING_LOBBY', 'ANSWERING', 'LOCKED', 'RESULT', 'FINISHED'
    this.currentQuestion = null;
    this.selectedAnswer = null;
    this.lastAnswerResult = null;
    this.initListeners();
  }

  initListeners() {
    window.realtimeBus.on('JOIN_SUCCESS', (data) => {
      this.currentPlayer = data.player;
      this.currentGamePin = data.game?.game_pin;
      this.currentGameState = 'WAITING_LOBBY';
      this.render();
      window.app.showToast(`Berhasil bergabung sebagai ${this.currentPlayer.name}!`, 'success');
      window.soundEngine.playLock();
    });

    window.realtimeBus.on('JOIN_REJECTED', (data) => {
      window.app.showToast(data.reason || 'Gagal bergabung ke game.', 'danger');
      window.soundEngine.playWrong();
    });

    window.realtimeBus.on('QUESTION_START', (data) => {
      if (!this.currentPlayer) return;
      this.currentQuestion = data.question;
      this.selectedAnswer = null;
      this.lastAnswerResult = null;
      this.currentGameState = 'ANSWERING';
      this.render();
      window.soundEngine.playLock();
    });

    window.realtimeBus.on('ANSWER_LOCKED', (data) => {
      if (data.playerId === this.currentPlayer?.id) {
        this.currentGameState = 'LOCKED';
        this.render();
        window.soundEngine.playLock();
      }
    });

    window.realtimeBus.on('QUESTION_ENDED', (data) => {
      if (!this.currentPlayer) return;
      const myAns = data.currentAnswers?.[this.currentPlayer.id];
      const myPlayerObj = data.players?.find(p => p.id === this.currentPlayer.id);
      if (myPlayerObj) this.currentPlayer = myPlayerObj;

      this.lastAnswerResult = {
        isCorrect: myAns ? myAns.isCorrect : false,
        scoreEarned: myAns ? myAns.scoreEarned : 0,
        correctAnswer: data.correctAnswer,
        explanation: data.explanation,
        totalScore: this.currentPlayer.total_score,
        rank: this.currentPlayer.rank
      };

      this.currentGameState = 'RESULT';
      this.render();

      if (this.lastAnswerResult.isCorrect) {
        window.soundEngine.playCorrect();
      } else {
        window.soundEngine.playWrong();
      }
    });

    window.realtimeBus.on('GAME_FINISHED', (data) => {
      if (!this.currentPlayer) return;
      const myPlayerObj = data.allPlayers?.find(p => p.id === this.currentPlayer.id);
      if (myPlayerObj) this.currentPlayer = myPlayerObj;
      this.currentGameState = 'FINISHED';
      this.render();
      window.soundEngine.playFanfare();
    });

    window.realtimeBus.on('GAME_CANCELLED', () => {
      if (this.currentPlayer) {
        window.app.showToast('Sesi game telah dihentikan oleh trainer.', 'warning');
        this.resetState();
        this.render();
      }
    });
  }

  resetState() {
    this.currentPlayer = null;
    this.currentGamePin = null;
    this.currentGameState = 'JOIN';
    this.currentQuestion = null;
    this.selectedAnswer = null;
    this.lastAnswerResult = null;
  }

  joinGame(pin, name) {
    if (!pin || !name.trim()) {
      window.app.showToast('Masukkan Game PIN dan Nama Anda!', 'warning');
      return;
    }

    const playerId = 'p_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4);

    window.realtimeBus.emit('PLAYER_JOIN', {
      pin: pin.trim(),
      name: name.trim(),
      playerId
    });
  }

  submitAnswer(answerOption) {
    if (this.selectedAnswer || this.currentGameState !== 'ANSWERING') return;

    this.selectedAnswer = answerOption;
    this.currentGameState = 'LOCKED';
    this.render();

    window.realtimeBus.emit('SUBMIT_ANSWER', {
      playerId: this.currentPlayer.id,
      answer: answerOption
    });
  }

  render() {
    const container = document.getElementById('main-view-container');
    if (!container || window.app.currentView !== 'participant') return '';

    let html = '';
    switch (this.currentGameState) {
      case 'JOIN':
        html = this.renderJoinScreen();
        break;
      case 'WAITING_LOBBY':
        html = this.renderWaitingLobby();
        break;
      case 'ANSWERING':
        html = this.renderAnsweringScreen();
        break;
      case 'LOCKED':
        html = this.renderLockedScreen();
        break;
      case 'RESULT':
        html = this.renderResultScreen();
        break;
      case 'FINISHED':
        html = this.renderFinalScreen();
        break;
      default:
        html = this.renderJoinScreen();
    }

    container.innerHTML = html;
    return html;
  }

  /* ==========================================================
     1. JOIN SCREEN
     ========================================================== */
  renderJoinScreen() {
    const urlParams = new URLSearchParams(window.location.search);
