          <div style="font-size: 3rem; margin-bottom: 0.5rem;" class="animate-bounce">🎯</div>

          <h2 style="font-size: 1.75rem; font-weight: 800; margin-bottom: 0.25rem;">
            Join Live Quiz
          </h2>
          <p class="text-muted" style="font-size: 0.9rem; margin-bottom: 1.75rem;">
            Training Agency Interactive Live Session
          </p>

          <form id="join-form" onsubmit="event.preventDefault(); window.participantView.joinGame(document.getElementById('input-pin').value, document.getElementById('input-name').value);">
            <div class="form-group text-left" style="margin-bottom: 1.25rem;">
              <label class="form-label" style="font-weight: 700;">Game PIN (6 Digit)</label>
              <input type="text" id="input-pin" class="form-control" style="font-size: 1.4rem; font-weight: 800; letter-spacing: 0.15em; text-align: center;" placeholder="Contoh: 483921" value="${prefillPin}" maxlength="8" required>
