  /* ==========================================================
     2. WAITING LOBBY
     ========================================================== */
  renderWaitingLobby() {
    return `
      <div class="animate-fade-in text-center" style="max-width: 440px; margin: 3rem auto;">
        <div class="glass-card" style="padding: 3rem 1.75rem; border: 2px solid var(--accent-emerald);">
          <div style="font-size: 3.5rem; margin-bottom: 1rem;" class="animate-pulse">🎉</div>

          <h2 style="font-size: 1.8rem; font-weight: 800; color: #6ee7b7; margin-bottom: 0.5rem;">
