          </div>
        </div>
      </div>
    `;
  }

  /* ==========================================================
     3. ANSWERING SCREEN (Color-coded Mobile Pads)
     ========================================================== */
  renderAnsweringScreen() {
    const q = this.currentQuestion;
    if (!q) return '<div class="text-center p-4">Menunggu soal...</div>';

    const isTF = q.question_type === 'true_false';

    return `
      <div class="animate-fade-in" style="max-width: 600px; margin: 0.5rem auto;">

        <!-- Question Header -->
        <div class="glass-card mb-3" style="padding: 1rem 1.25rem; text-align: center;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;">
            <span class="badge badge-primary">Soal #${q.order_index || 1}</span>
            <span style="font-size: 0.85rem; color: var(--text-muted);">👤 ${this.currentPlayer?.name}</span>
          </div>

          <h3 style="font-size: 1.2rem; font-weight: 700; line-height: 1.35; color: #fff;">
            ${q.question}
          </h3>
        </div>

        <!-- Answer Touch Pad Buttons -->
        ${isTF ? `
          <div class="grid-2">
            <button class="answer-card opt-b flex-center" style="font-size: 1.4rem; padding: 2rem 1rem;" onclick="window.participantView.submitAnswer('A')">
              <span class="opt-shape">🔷</span>
              <span class="opt-text text-center">Benar (True)</span>
            </button>
            <button class="answer-card opt-a flex-center" style="font-size: 1.4rem; padding: 2rem 1rem;" onclick="window.participantView.submitAnswer('B')">
              <span class="opt-shape">🔺</span>
              <span class="opt-text text-center">Salah (False)</span>
            </button>
          </div>
        ` : `
          <div class="answer-grid">
            <button class="answer-card opt-a" onclick="window.participantView.submitAnswer('A')">
              <span class="opt-shape">▲</span>
              <span class="opt-text">${q.option_a}</span>
            </button>
            <button class="answer-card opt-b" onclick="window.participantView.submitAnswer('B')">
              <span class="opt-shape">◆</span>
              <span class="opt-text">${q.option_b}</span>
            </button>
            <button class="answer-card opt-c" onclick="window.participantView.submitAnswer('C')">
              <span class="opt-shape">●</span>
              <span class="opt-text">${q.option_c || '-'}</span>
            </button>
            <button class="answer-card opt-d" onclick="window.participantView.submitAnswer('D')">
              <span class="opt-shape">■</span>
              <span class="opt-text">${q.option_d || '-'}</span>
            </button>
          </div>
        `}

      </div>
    `;
  }

  /* ==========================================================
     4. ANSWER LOCKED SCREEN
     ========================================================== */
  renderLockedScreen() {
    return `
      <div class="animate-fade-in text-center" style="max-width: 440px; margin: 3rem auto;">
        <div class="glass-card" style="padding: 3rem 1.5rem; border: 2px solid var(--primary);">
          <div style="font-size: 3.5rem; margin-bottom: 1rem;" class="animate-float">🔒</div>

          <h2 style="font-size: 1.6rem; font-weight: 800; color: #fff; margin-bottom: 0.5rem;">
            Jawaban Terkunci!
          </h2>

          <p class="text-muted" style="font-size: 0.95rem; margin-bottom: 1.5rem;">
            Pilihan Anda telah tercatat. Menunggu waktu habis dan peserta lain selesai menjawab...
          </p>

          <div class="badge badge-primary animate-pulse" style="font-size: 0.9rem; padding: 0.4rem 1rem;">
            ⏱️ Menunggu Kunci Jawaban...
          </div>
        </div>
      </div>
    `;
  }

  /* ==========================================================
     5. QUESTION RESULT SCREEN (Score Feedback & Explanation)
     ========================================================== */
  renderResultScreen() {
    const res = this.lastAnswerResult;
    if (!res) return '<div class="text-center p-4">Menunggu hasil...</div>';

    return `
      <div class="animate-fade-in text-center" style="max-width: 480px; margin: 2rem auto;">
        <div class="glass-card ${res.isCorrect ? 'animate-bounce' : 'animate-shake'}" style="padding: 2.5rem 1.75rem; border: 2px solid ${res.isCorrect ? 'var(--accent-emerald)' : 'var(--danger)'};">

          <div style="font-size: 3.8rem; margin-bottom: 0.5rem;">
            ${res.isCorrect ? '🌟' : '❌'}
          </div>

          <h2 style="font-size: 1.8rem; font-weight: 800; color: ${res.isCorrect ? '#34d399' : '#f87171'}; margin-bottom: 0.25rem;">
            ${res.isCorrect ? 'JAWABAN BENAR!' : 'JAWABAN SALAH'}
          </h2>

          <div style="font-size: 2.2rem; font-weight: 900; color: #ffffff; margin: 0.75rem 0;">
            ${res.isCorrect ? `+${res.scoreEarned.toLocaleString()} Poin` : '+0 Poin'}
          </div>

          <div style="display: flex; justify-content: center; gap: 1rem; margin-bottom: 1.5rem;">
            <span class="badge badge-primary" style="font-size: 0.95rem;">🏆 Rank: #${res.rank || '-'}</span>
            <span class="badge badge-cyan" style="font-size: 0.95rem;">⭐ Total: ${(res.totalScore || 0).toLocaleString()} pts</span>
          </div>

          ${res.explanation ? `
            <div style="background: rgba(0, 0, 0, 0.35); padding: 1rem; border-radius: var(--radius-md); text-align: left; font-size: 0.88rem; color: #d1d5db; margin-top: 1rem; border-left: 3px solid var(--accent-emerald);">
              💡 <strong>Pembahasan:</strong> ${res.explanation}
            </div>
          ` : ''}

          <p class="text-muted mt-4" style="font-size: 0.85rem;">
            Tunggu trainer untuk melanjutkan ke soal berikutnya...
          </p>
        </div>
      </div>
    `;
  }

  /* ==========================================================
     6. FINAL SCORE SUMMARY SCREEN
     ========================================================== */
  renderFinalScreen() {
    const p = this.currentPlayer;
    const isWinner = p && p.rank <= 3;

    return `
      <div class="animate-fade-in text-center" style="max-width: 480px; margin: 2rem auto;">
        <div class="glass-card" style="padding: 2.5rem 1.75rem; border: 2px solid ${isWinner ? '#fbbf24' : 'var(--primary)'};">

          <div style="font-size: 4rem; margin-bottom: 0.5rem;" class="animate-bounce">
            ${p?.rank === 1 ? '🥇' : p?.rank === 2 ? '🥈' : p?.rank === 3 ? '🥉' : '🎖️'}
          </div>

          <h2 style="font-size: 1.8rem; font-weight: 800; color: #fff; margin-bottom: 0.25rem;">
            Game Selesai!
          </h2>

          <p class="text-muted" style="margin-bottom: 1.5rem;">Terima kasih telah berpartisipasi dalam training.</p>

          <div class="glass-card mb-4" style="background: rgba(15, 23, 42, 0.7);">
            <div style="font-size: 1rem; color: var(--text-muted); margin-bottom: 0.2rem;">Peringkat Akhir Anda:</div>
            <div style="font-size: 2.8rem; font-weight: 900; color: ${isWinner ? '#fbbf24' : '#fff'};">
              Rank #${p?.rank || '-'}
            </div>
            <div style="font-size: 1.25rem; font-weight: 700; color: #6ee7b7; margin-top: 0.3rem;">
              ${(p?.total_score || 0).toLocaleString()} Total Points
            </div>
            <div style="font-size: 0.9rem; color: var(--text-muted); margin-top: 0.5rem;">
              Jawaban Benar: <strong>${p?.correct_count || 0}</strong> Pertanyaan
            </div>
          </div>

          <button class="btn btn-outline" style="width: 100%;" onclick="window.participantView.resetState(); window.participantView.render();">
            🔄 Main Game Lain
          </button>
        </div>
      </div>
    `;
  }
}

window.participantView = new ParticipantView();

/**
 * History & Export View - Training session history and participant records
 * Implements PRD Section 5 (History & Export), Section 10 (Participant Record), & Section 11 (Ranking)
 */
class HistoryExportView {
  constructor() {
    this.currentTab = 'sessions'; // 'sessions' or 'participants'
  }

  setTab(tab) {
    this.currentTab = tab;
    window.app.renderCurrentView();
  }

  render() {
    const games = window.storage.getGamesHistory();
    const records = window.storage.getParticipantRecords();

    return `
      <div class="animate-fade-in">
        <div class="glass-card mb-6">
          <div class="card-header-flex">
            <div>
              <div class="badge badge-primary mb-2">TRAINING AGENCY DATABASE</div>
              <h1 style="font-size: 1.8rem; font-weight: 800;">Riwayat Training & Rekap Peserta</h1>
              <p class="text-muted">Pantau evaluasi pemahaman seluruh peserta yang telah mengikuti kuis interaktif.</p>
            </div>

            <div style="display: flex; gap: 0.75rem;">
              <button class="btn btn-outline" onclick="window.historyExportView.exportAllJSON()">
                📦 Export JSON
              </button>
              <button class="btn btn-primary" onclick="window.historyExportView.exportAllCSV()">
                📥 Export ke Excel / CSV
              </button>
            </div>
          </div>

          <!-- Navigation Tabs -->
          <div style="display: flex; gap: 0.5rem; border-bottom: 1px solid var(--border-glass); padding-bottom: 0.5rem; margin-top: 1.5rem;">
            <button class="btn ${this.currentTab === 'sessions' ? 'btn-primary' : 'btn-ghost'}" onclick="window.historyExportView.setTab('sessions')">
              🎮 Sesi Live Game (${games.length})
            </button>
            <button class="btn ${this.currentTab === 'participants' ? 'btn-primary' : 'btn-ghost'}" onclick="window.historyExportView.setTab('participants')">
              👥 Rekap Hasil Peserta (${records.length})
            </button>
          </div>
        </div>

        ${this.currentTab === 'sessions' ? this.renderSessionsTab(games) : this.renderParticipantsTab(records)}
      </div>
    `;
  }

  renderSessionsTab(games) {
    return `
      <div class="glass-card">
        <h3 style="font-size: 1.25rem; font-weight: 700; margin-bottom: 1rem;">Daftar Sesi Game Training</h3>

        <div class="table-responsive">
          <table class="custom-table">
            <thead>
              <tr>
                <th>Tanggal & Waktu</th>
                <th>Nama Training / Kuis</th>
                <th>Level / Topik</th>
                <th>Trainer</th>
                <th>PIN</th>
                <th>Peserta</th>
                <th>Juara 1</th>
                <th>Avg Skor</th>
                <th>Aksi</th>
              </tr>
            </thead>
            <tbody>
              ${games.length === 0 ? `
                <tr><td colspan="9" class="text-center text-muted" style="padding: 2.5rem;">Belum ada sesi training yang tersimpan.</td></tr>
              ` : games.map(g => {
                const winner = g.players && g.players.length > 0 ? g.players[0] : null;
                return `
                  <tr>
                    <td>${new Date(g.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</td>
                    <td><strong>${g.training_name || g.quiz_name}</strong></td>
                    <td><span class="badge badge-cyan">${g.level || 'Basic'}</span></td>
                    <td>${g.trainer_name || 'Trainer'}</td>
                    <td><span class="badge badge-primary">${g.game_pin}</span></td>
                    <td>${g.participant_count} Peserta</td>
                    <td>${winner ? `👑 <strong>${winner.name}</strong>` : '-'}</td>
                    <td><strong>${(g.average_score || 0).toLocaleString()}</strong></td>
                    <td>
                      <button class="btn btn-ghost" style="padding: 0.3rem 0.6rem; font-size: 0.85rem;" onclick="window.historyExportView.exportSingleSessionCSV('${g.id}')">
                        📥 CSV
                      </button>
                    </td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }

  renderParticipantsTab(records) {
    return `
      <div class="glass-card">
        <h3 style="font-size: 1.25rem; font-weight: 700; margin-bottom: 1rem;">Rekapitulasi Hasil Kuis per Peserta</h3>

        <div class="table-responsive">
          <table class="custom-table">
            <thead>
              <tr>
                <th>Nama Peserta</th>
                <th>Training / Kuis</th>
                <th>Level</th>
                <th>Tanggal</th>
                <th>Peringkat</th>
                <th>Skor</th>
                <th>Benar</th>
                <th>Kelulusan %</th>
              </tr>
            </thead>
            <tbody>
              ${records.length === 0 ? `
                <tr><td colspan="8" class="text-center text-muted" style="padding: 2.5rem;">Belum ada rekap peserta yang tercatat.</td></tr>
              ` : records.map(r => `
                <tr>
                  <td><strong>${r.name}</strong></td>
                  <td>${r.training_name || r.quiz_name}</td>
                  <td><span class="badge badge-cyan">${r.level || 'Basic'}</span></td>
                  <td>${new Date(r.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}</td>
                  <td><strong>#${r.rank}</strong></td>
                  <td><strong style="color: #6ee7b7;">${(r.score || 0).toLocaleString()}</strong></td>
                  <td>${r.correct_count} / ${r.total_questions}</td>
                  <td>
                    <span class="badge ${r.completion_percent >= 70 ? 'badge-success' : 'badge-warning'}">
                      ${r.completion_percent}%
                    </span>
                  </td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }

  exportCurrentGameCSV() {
    const game = window.gameManager.getActiveGame();
    if (!game || !game.players || game.players.length === 0) {
      window.app.showToast('Tidak ada data peserta untuk diekspor.', 'warning');
      return;
    }

    let csv = `Training Name,${game.training_name || game.quiz_name}\n`;
    csv += `Game PIN,${game.game_pin}\n`;
    csv += `Trainer,${game.trainer_name}\n`;
    csv += `Date,${new Date().toISOString()}\n\n`;
    csv += `Rank,Nama Peserta,Total Skor,Jawaban Benar,Total Pertanyaan,Akurasi %\n`;

    game.players.forEach(p => {
      const accuracy = Math.round(((p.correct_count || 0) / game.total_questions) * 100);
      csv += `${p.rank},"${p.name}",${p.total_score},${p.correct_count || 0},${game.total_questions},${accuracy}%\n`;
    });

    this.downloadFile(csv, `Hasil_Quiz_${game.quiz_name.replace(/\s+/g, '_')}_PIN_${game.game_pin}.csv`, 'text/csv');
    window.app.showToast('Hasil game berhasil diexport ke CSV! 📥', 'success');
  }

  exportSingleSessionCSV(sessionId) {
    const games = window.storage.getGamesHistory();
    const game = games.find(g => g.id === sessionId);
    if (!game) return;

    let csv = `Training Name,${game.training_name || game.quiz_name}\n`;
    csv += `Game PIN,${game.game_pin}\n`;
    csv += `Trainer,${game.trainer_name}\n`;
    csv += `Date,${game.date}\n\n`;
    csv += `Rank,Nama Peserta,Total Skor,Jawaban Benar,Total Pertanyaan\n`;

    (game.players || []).forEach(p => {
      csv += `${p.rank},"${p.name}",${p.score || p.total_score},${p.correct || p.correct_count || 0},${game.total_questions}\n`;
    });

    this.downloadFile(csv, `Sesi_${game.game_pin}_${game.quiz_name.replace(/\s+/g, '_')}.csv`, 'text/csv');
  }

  exportAllCSV() {
    const records = window.storage.getParticipantRecords();
    if (records.length === 0) {
      window.app.showToast('Belum ada data rekap peserta untuk diexport.', 'warning');
      return;
    }

    let csv = `ID,Nama Peserta,Training Name,Quiz Name,Level,Subject,Trainer,Tanggal,Rank,Skor,Benar,Total Soal,Completion %\n`;
    records.forEach(r => {
      csv += `"${r.id}","${r.name}","${r.training_name}","${r.quiz_name}","${r.level}","${r.subject}","${r.trainer_name}","${r.date}",${r.rank},${r.score},${r.correct_count},${r.total_questions},${r.completion_percent}%\n`;
    });

    this.downloadFile(csv, `Training_Agency_Rekap_Peserta_${Date.now()}.csv`, 'text/csv');
    window.app.showToast('Data peserta berhasil diexport ke CSV! 📥', 'success');
  }

  exportAllJSON() {
    const data = {
      quizzes: window.storage.getQuizzes(),
      games_history: window.storage.getGamesHistory(),
      participant_records: window.storage.getParticipantRecords(),
      exported_at: new Date().toISOString()
    };
    const jsonStr = JSON.stringify(data, null, 2);
    this.downloadFile(jsonStr, `Training_Agency_Backup_${Date.now()}.json`, 'application/json');
    window.app.showToast('Backup JSON berhasil didownload! 📦', 'success');
  }

  downloadFile(content, fileName, mimeType) {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }
}

window.historyExportView = new HistoryExportView();

/**
 * App Core Controller & Routing
 * Training Agency Live Quiz - Version 1.0 (MVP)
 */
class App {
  constructor() {
    this.currentView = 'dashboard'; // 'dashboard', 'trainer-host', 'participant', 'history'
    this.init();
  }

  init() {
    // Check URL parameters for direct join
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.has('pin')) {
      this.currentView = 'participant';
    } else if (urlParams.has('view')) {
      this.currentView = urlParams.get('view');
    }

    this.renderCurrentView();
    this.updateNavState();
  }

  showView(viewName) {
    this.currentView = viewName;
    this.renderCurrentView();
    this.updateNavState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  updateNavState() {
    document.querySelectorAll('.nav-link').forEach(link => {
      if (link.getAttribute('data-view') === this.currentView) {
        link.classList.add('active');
      } else {
        link.classList.remove('active');
      }
    });
  }

  renderCurrentView() {
    const container = document.getElementById('main-view-container');
    if (!container) return;

    switch (this.currentView) {
      case 'dashboard':
        container.innerHTML = window.adminDashboardView.render();
        break;
      case 'trainer-host':
        container.innerHTML = window.trainerHostView.render();
        break;
      case 'participant':
        window.participantView.render();
        break;
      case 'history':
        container.innerHTML = window.historyExportView.render();
        break;
      default:
        container.innerHTML = window.adminDashboardView.render();
    }
  }

  showToast(message, type = 'info') {
    let container = document.getElementById('toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    const icon = type === 'success' ? '✅' : type === 'danger' ? '⚠️' : type === 'warning' ? '🔔' : 'ℹ️';
    toast.innerHTML = `<span>${icon}</span> <span>${message}</span>`;
    container.appendChild(toast);

    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateX(100%)';
      toast.style.transition = 'all 0.3s ease';
      setTimeout(() => toast.remove(), 300);
    }, 3500);
  }

  openSettingsModal() {
    const config = window.storage.getSupabaseConfig();
    const modalContainer = document.getElementById('modal-container');
    if (!modalContainer) return;

    modalContainer.innerHTML = `
      <div class="modal-backdrop show" id="settings-modal">
        <div class="modal-content" style="max-width: 650px;">
          <div class="modal-header">
            <div class="modal-title">
              <span>⚙️ Pengaturan & Cloud Supabase (Opsional)</span>
            </div>
            <button class="btn btn-ghost btn-icon" onclick="document.getElementById('settings-modal').remove()">✕</button>
          </div>

          <div class="modal-body">
            <p class="text-muted" style="margin-bottom: 1.25rem;">
              Secara default, aplikasi berjalan langsung dengan <strong>Zero-Config Realtime Engine (BroadcastChannel + LocalStorage)</strong> yang mendukung multi-tab dan bot simulasi. Anda juga dapat menghubungkannya ke cloud Supabase bila diinginkan.
            </p>

            <div class="form-group">
              <label class="form-label">Supabase Project URL</label>
              <input type="text" id="cfg-supabase-url" class="form-control" placeholder="https://xyzcompany.supabase.co" value="${config.url || ''}">
            </div>

            <div class="form-group">
              <label class="form-label">Supabase Anon Public Key</label>
              <input type="password" id="cfg-supabase-key" class="form-control" placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..." value="${config.anonKey || ''}">
            </div>

            <div class="glass-card mt-4" style="background: rgba(15, 23, 42, 0.5); padding: 1rem;">
              <div style="font-size: 0.88rem; font-weight: 700; color: #a5b4fc; margin-bottom: 0.3rem;">
                📄 SQL Database Schema
              </div>
              <div style="font-size: 0.82rem; color: var(--text-muted);">
                File skema PostgreSQL lengkap dengan RLS dan Realtime replication siap dijalankan di Supabase SQL Editor:
                <br><code>d:/AI 2/Game/database/schema.sql</code>
              </div>
            </div>
          </div>

          <div class="modal-footer">
            <button class="btn btn-outline" onclick="document.getElementById('settings-modal').remove()">Batal</button>
            <button class="btn btn-primary" onclick="window.app.saveSettings()">Simpan Pengaturan</button>
          </div>
        </div>
      </div>
    `;
  }

  saveSettings() {
    const url = document.getElementById('cfg-supabase-url')?.value.trim() || '';
    const anonKey = document.getElementById('cfg-supabase-key')?.value.trim() || '';

    window.storage.saveSupabaseConfig({
      url,
      anonKey,
      enabled: Boolean(url && anonKey)
    });

    this.showToast('Pengaturan berhasil disimpan!', 'success');
    document.getElementById('settings-modal')?.remove();
  }
}

// Instantiate and initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  window.app = new App();
});

