class App {
  constructor() {
    this.currentView = 'dashboard';
  }

  init() {
    // Check URL parameters for direct join
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.has('pin')) {
      this.currentView = 'participant';
    } else if (urlParams.has('view')) {
      this.currentView = urlParams.get('view');
    }

    this.renderCurrentView();
    this.updateNavState();
  }

  showView(viewName) {
    this.currentView = viewName;
    this.renderCurrentView();
    this.updateNavState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  updateNavState() {
    document.querySelectorAll('.nav-link').forEach(link => {
      if (link.getAttribute('data-view') === this.currentView) {
        link.classList.add('active');
      } else {
        link.classList.remove('active');
      }
    });
  }

  renderCurrentView() {
    const container = document.getElementById('main-view-container');
    if (!container) return;

    switch (this.currentView) {
      case 'dashboard':
        container.innerHTML = window.adminDashboardView.render();
        break;
      case 'trainer-host':
        container.innerHTML = window.trainerHostView.render();
        break;
      case 'participant':
        container.innerHTML = window.participantView.render();
        break;
      case 'history':
        container.innerHTML = window.historyExportView.render();
        break;
      default:
        container.innerHTML = window.adminDashboardView.render();
    }
  }

  showToast(message, type = 'info') {
    let container = document.getElementById('toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    const icon = type === 'success' ? '✅' : type === 'danger' ? '⚠️' : type === 'warning' ? '🔔' : 'ℹ️';
    toast.innerHTML = `<span>${icon}</span> <span>${message}</span>`;
    container.appendChild(toast);

    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateX(100%)';
      toast.style.transition = 'all 0.3s ease';
      setTimeout(() => toast.remove(), 300);
    }, 3500);
  }

  openSettingsModal() {
    const config = window.storage.getSupabaseConfig();
    const modalContainer = document.getElementById('modal-container');
    if (!modalContainer) return;

    modalContainer.innerHTML = `
      <div class="modal-backdrop show" id="settings-modal">
        <div class="modal-content" style="max-width: 650px;">
          <div class="modal-header">
            <div class="modal-title">
              <span>⚙️ Pengaturan & Cloud Supabase (Opsional)</span>
            </div>
            <button class="btn btn-ghost btn-icon" onclick="document.getElementById('settings-modal').remove()">✕</button>
          </div>

          <div class="modal-body">
            <p class="text-muted" style="margin-bottom: 1.25rem;">
              Secara default, aplikasi berjalan langsung dengan <strong>Zero-Config Realtime Engine (BroadcastChannel + LocalStorage)</strong> yang mendukung multi-tab dan bot simulasi. Anda juga dapat menghubungkannya ke cloud Supabase bila diinginkan.
            </p>

            <div class="form-group">
              <label class="form-label">Supabase Project URL</label>
              <input type="text" id="cfg-supabase-url" class="form-control" placeholder="https://xyzcompany.supabase.co" value="${config.url || ''}">
            </div>

            <div class="form-group">
              <label class="form-label">Supabase Anon Public Key</label>
              <input type="password" id="cfg-supabase-key" class="form-control" placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..." value="${config.anonKey || ''}">
            </div>

            <div class="glass-card mt-4" style="background: rgba(15, 23, 42, 0.5); padding: 1rem;">
              <div style="font-size: 0.88rem; font-weight: 700; color: #a5b4fc; margin-bottom: 0.3rem;">
                📄 SQL Database Schema
              </div>
              <div style="font-size: 0.82rem; color: var(--text-muted);">
                File skema PostgreSQL lengkap dengan RLS dan Realtime replication siap dijalankan di Supabase SQL Editor:
                <br><code>d:/AI 2/Game/database/schema.sql</code>
              </div>
            </div>
          </div>

          <div class="modal-footer">
            <button class="btn btn-outline" onclick="document.getElementById('settings-modal').remove()">Batal</button>
            <button class="btn btn-primary" onclick="window.app.saveSettings()">Simpan Pengaturan</button>
          </div>
        </div>
      </div>
    `;
  }

  saveSettings() {
    const url = document.getElementById('cfg-supabase-url')?.value.trim() || '';
    const anonKey = document.getElementById('cfg-supabase-key')?.value.trim() || '';

    window.storage.saveSupabaseConfig({
      url,
      anonKey,
      enabled: Boolean(url && anonKey)
    });

    this.showToast('Pengaturan berhasil disimpan!', 'success');
    document.getElementById('settings-modal')?.remove();
  }
}

// Instantiate and initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  window.app = new App();
  window.app.init();
});

