if (this.activeGame.status !== 'LOBBY' && this.activeGame.status !== 'WAITING') {
  // Allow rejoin if player already exists
  const existing = this.activeGame.players.find(p => p.id === playerId || p.name.toLowerCase() === name.toLowerCase());
  if (existing) {
    window.realtimeBus.emit('JOIN_SUCCESS', {
      playerId: existing.id,
      player: existing,
      game: this.getPublicGameState()
    });
  } else {
    window.realtimeBus.emit('JOIN_REJECTED', {
      reason: 'Game sudah dimulai atau selesai.',
      playerId
    });
  }
  return;
}

