class GameManager {
  constructor() {
    this.activeGame = null;
    this.timerInterval = null;
    this.timeRemaining = 0;
    this.isHost = sessionStorage.getItem('ta_is_game_host') === 'true';
    this.initEventListeners();
  }

  initEventListeners() {
    // Listen to participant actions (ONLY host handles these)
    window.realtimeBus.on('PLAYER_JOIN', (data) => {
      if (this.isHost) {
        this.handlePlayerJoin(data);
      }
    });

    window.realtimeBus.on('SUBMIT_ANSWER', (data) => {
      if (this.isHost) {
        this.handlePlayerAnswer(data);
      }
    });
  }

  /**
   * Generate unique 6-digit Game PIN
   */
  generatePIN() {
    return Math.floor(100000 + Math.random() * 900000).toString();
  }

  /**
   * Create and Start a new Live Game Session
   */
  createGame(quizId) {
    const quiz = window.storage.getQuizById(quizId);
    if (!quiz || !quiz.questions || quiz.questions.length === 0) {
      throw new Error('Kuis tidak memiliki pertanyaan yang valid.');
    }

    this.isHost = true;
    sessionStorage.setItem('ta_is_game_host', 'true');

    const pin = this.generatePIN();
    this.activeGame = {
      id: 'game_' + Date.now(),
      quiz_id: quiz.id,
      quiz_name: quiz.quiz_name,
      training_name: quiz.training_name || quiz.quiz_name,
      level: quiz.level || 'Basic',
      subject: quiz.subject || 'General',
      trainer_name: quiz.trainer_name || 'Trainer',
      game_pin: pin,
      status: 'LOBBY', // WAITING, LOBBY, QUESTION, RESULT, LEADERBOARD, FINISHED, CANCELLED
      current_question_index: 0,
      total_questions: quiz.questions.length,
      questions: JSON.parse(JSON.stringify(quiz.questions)),
      players: [],
      current_answers: {}, // playerId -> answer data
      start_time: new Date().toISOString(),
      max_participants: 50
    };

    // Save active game to storage for multi-tab recovery
    this.saveActiveSession();

    // Broadcast GAME_CREATED event
    window.realtimeBus.emit('GAME_CREATED', this.getPublicGameState());
    return this.activeGame;
  }

